import React from "react";
import axiosInstance from "../configurations/instance";
import LeftSlidebarChecker from "./leftSlidebarChecker";

class CheckerEvents extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null,
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/checker-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) =>
        console.error("Ошибка при загрузке событий проверяющего:", error)
      );
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/checker/${id}`)
      .then((response) => {
        this.setState({ selectedEvent: response.data });
      })
      .catch((error) =>
        console.error("Ошибка при загрузке деталей события:", error)
      );
  };

  getStatus = (eventDate) => {
    const now = new Date();
    const eventStart = new Date(eventDate);
    const diffInMs = now - eventStart;
    const diffInHours = diffInMs / (1000 * 60 * 60);

    if (diffInHours < 0) {
      return "В ожидании";
    } else if (diffInHours <= 12) {
      return "В процессе";
    } else {
      return "Завершено";
    }
  };

  render() {
    const { events, selectedEvent } = this.state;

    return (
      <div className="checker-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebarChecker />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Дата проведения</th>
                  <th>Статус</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => (
                  <tr key={event.eventId}>
                    <td>{index + 1}</td>
                    <td>{event.eventName}</td>
                    <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                    <td>{this.getStatus(event.eventDate)}</td>
                    <td>
                      <button
                        className="check"
                        onClick={() => this.handleView(event.eventId)}
                      >
                        Просмотр
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {selectedEvent && (
              <div className="checkerViewForm">
                <h1>Детали события</h1>
                <h3>Название мероприятия</h3>
                <div className="field">{selectedEvent.eventName}</div>

                <h3>Тип мероприятия</h3>
                <div className="field">{selectedEvent.eventType}</div>

                <h3>Дата проведения</h3>
                <div className="field">
                  {new Date(selectedEvent.eventDate).toLocaleString()}
                </div>

                <h3>Проверяющие</h3>
                {selectedEvent.emailFields.map((email, index) => (
                  <div key={index} className="field">{email}</div>
                ))}

                <h3>Участники</h3>
                {selectedEvent.participants.map((participant, index) => (
                  <div key={index} className="participant">
                    <h4>Участник №{index + 1}</h4>
                    <div className="field">
                      <strong>ФИО:</strong> {participant.name}
                    </div>
                    <div className="field">
                      <strong>ИИН:</strong> {participant.iin}
                    </div>
                  </div>
                ))}
                <button type="button" className="add-button" onClick={this.handleSubmit}>
                  Сохранить
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default CheckerEvents;
